}

num_deriv <- function(density_function, x, h = 1e-5) {
  (compute_log_density(density_function, x + h) - compute_log_density(density_function, x - h)) / (2 * h)
}

ars_init <- function(density_function, domain, n_init = 4) {
  lower <- domain[1]
