  }
  hx <- compute_log_density(density_function, x)
  dhx <- num_deriv(density_function, x)
  ord <- order(x)
  list(x = x[ord], hx = hx[ord], dhx = dhx[ord], lower = lower, upper = upper)
}

update_hulls <- function(state, x_new, density_function) {
  hx_new <- compute_log_density(density_function, x_new)
  dhx_new <- num_deriv(density_function, x_new)
  x <- c(state$x, x_new)
  hx <- c(state$hx, hx_new)
  dhx <- c(state$dhx, dhx_new)
  ord <- order(x)
  x <- x[ord]
  hx <- hx[ord]
  dhx <- dhx[ord]
  k <- length(x)
  for (i in 1:(k - 1)) {
    if (dhx[i] < dhx[i+1] - 1e-7) {
      stop("Non-log-concave density detected.")
    }
  }
  state$x <- x
  state$hx <- hx
  state$dhx <- dhx
  return(state)
}

sample_upper_hull <- function(state) {
  x <- state$x
  hx <- state$hx
  dhx <- state$dhx
  k <- length(x)
  z <- numeric(k + 1)
  z[1] <- state$lower
  z[k+1] <- state$upper
  for (i in 1:(k - 1)) {
    denom <- dhx[i] - dhx[i+1]
    if (abs(denom) < 1e-12) {
      z[i+1] <- (x[i] + x[i+1]) / 2
    } else {
      z[i+1] <- (hx[i+1] - hx[i] - x[i+1]*dhx[i+1] + x[i]*dhx[i]) / denom
    }
  }
  z[1] <- max(z[1], state$lower)
  z[k+1] <- min(z[k+1], state$upper)
  for (i in 2:k) {
    if (z[i] <= x[i-1]) z[i] <- x[i-1] + 1e-6
    if (z[i] >= x[i]) z[i] <- x[i] - 1e-6
  }
  log_weights <- numeric(k)
  for (i in 1:k) {
    d <- dhx[i]
    c_val <- hx[i] - d * x[i]
    if (abs(d) < 1e-10) {
      log_weights[i] <- c_val + log(z[i+1] - z[i])
    } else {
      term1 <- d * z[i+1]
      term2 <- d * z[i]
      max_t <- max(term1, term2)
      log_diff <- max_t + log(abs(exp(term1 - max_t) - exp(term2 - max_t))) - log(abs(d))
      log_weights[i] <- c_val + log_diff
    }
  }
  max_lw <- max(log_weights)
  weights <- exp(log_weights - max_lw)
  probs <- weights / sum(weights)
  i <- sample(k, 1, prob = probs)
  d <- dhx[i]
  z_left <- z[i]
  z_right <- z[i+1]
  u_uni <- runif(1)
  if (abs(d) < 1e-10) {
    x_star <- z_left + u_uni * (z_right - z_left)
  } else {
    x_star <- z_left + log(1.0 + u_uni * (exp(d * (z_right - z_left)) - 1.0)) / d
  }
  list(x_star = x_star, z = z)
}

eval_lower_hull <- function(state, x_star) {
  x <- state$x
  hx <- state$hx
  k <- length(x)
  if (x_star < x[1] || x_star > x[k]) return(-Inf)
  idx <- max(which(x <= x_star))
  if (idx == k) idx <- k - 1
  hx[idx] + (hx[idx+1] - hx[idx]) * (x_star - x[idx]) / (x[idx+1] - x[idx])
}

ars <- function(density_function, domain, n = 1000) {
  if (!is.function(density_function)) stop("density_function must be a function.")
  if (!is.numeric(domain) || length(domain) != 2 || domain[1] >= domain[2]) stop("Invalid domain.")
  if (!is.numeric(n) || length(n) != 1 || n <= 0 || n != round(n)) stop("Invalid n.")
  state <- ars_init(density_function, domain)
  samples <- numeric(n)
  accepted <- 0
  while (accepted < n) {
    res <- sample_upper_hull(state)
    x_star <- res$x_star
    x <- state$x
    hx <- state$hx
    dhx <- state$dhx
    idx <- max(which(res$z <= x_star))
    if (idx > length(dhx)) idx <- length(dhx)
    if (idx < 1) idx <- 1
    u_star <- hx[idx] + dhx[idx] * (x_star - x[idx])
    w <- runif(1)
    l_star <- eval_lower_hull(state, x_star)
    if (log(w) <= l_star - u_star) {
      accepted <- accepted + 1
      samples[accepted] <- x_star
      next
    }
    h_star <- compute_log_density(density_function, x_star)
    if (!is.finite(h_star)) {
      state <- update_hulls(state, x_star, density_function)
      next
    }
    if (log(w) <= h_star - u_star) {
      accepted <- accepted + 1
      samples[accepted] <- x_star
    }
    state <- update_hulls(state, x_star, density_function)
  }
  return(samples)
}

